#!/usr/bin/env python3
import os,base64,pathlib
DEST=pathlib.Path(os.path.dirname(os.path.abspath(__file__)))
FILES={
    'static/app.js':'',
    'templates/index.html':'',
}
for rel,b64 in FILES.items():
    p=DEST/rel; p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes(base64.b64decode(b64)); print(f"ok {rel}")
print("Done. git add -A && git commit -m v10.9-debug && git push origin main")
